WITH valid AS (SELECT *, ROUND(balance * 0.85, 2) AS balance_scaled, CASE WHEN status IN ('FROZEN', 'CLOSED') THEN 'Priority' ELSE 'Other' END AS status_group FROM accounts WHERE opened_date >= DATE '2023-06-18' AND status IS NOT NULL) SELECT s.*, x.merchant FROM valid s JOIN LATERAL (SELECT c.merchant FROM transactions c WHERE c.account_id = s.id ORDER BY c.txn_time DESC, c.id DESC LIMIT 1) x ON TRUE
